/**
 * Access to the real stack that `scripts/real-stack.mjs` started: the server's
 * address, an administrator signed in over HTTP (cookie session and CSRF
 * token, like a browser), and the switch that stops and starts the server.
 *
 * The administrator's password was generated by the server's own command line
 * tool for this run; it is read from a file that only exists while the stack
 * is up and is never printed.
 */
import fs from 'node:fs';
import { createApiClient, type ApiClient } from '@realtimedocs/contracts';

interface Control {
  origin: string;
  controlUrl: string;
  controlToken: string;
  adminEmail: string;
  adminPassword: string;
}

function readControl(): Control {
  const file = process.env.RD_REAL_CONTROL;
  if (!file || !fs.existsSync(file)) {
    throw new Error(
      'The real stack is not running. Start these tests with `pnpm --filter @realtimedocs/desktop run test:real`.',
    );
  }
  return JSON.parse(fs.readFileSync(file, 'utf8')) as Control;
}

const control = readControl();

/** `http://127.0.0.1:4440`: the origin the server reports as its public one. */
export const SERVER_ORIGIN = control.origin;

/** One browser-like profile: a cookie jar, the CSRF token, and the typed API client on top. */
export class Account {
  private readonly cookies = new Map<string, string>();
  private csrf: string | null = null;
  readonly api: ApiClient;

  constructor(readonly origin: string = SERVER_ORIGIN) {
    this.api = createApiClient({
      baseUrl: origin,
      credentials: 'include',
      getCsrfToken: () => this.csrf,
      fetch: (input, init) => this.fetch(input, init),
    });
  }

  /** A request with this profile's cookies, like the browser would send it. */
  async fetch(input: string | URL | Request, init?: RequestInit): Promise<Response> {
    const headers = new Headers(init?.headers);
    if (this.cookies.size > 0) {
      headers.set(
        'cookie',
        [...this.cookies].map(([name, value]) => `${name}=${value}`).join('; '),
      );
    }
    // A browser on the server's own pages sends this origin.
    headers.set('origin', this.origin);
    const response = await fetch(input, { ...init, headers, redirect: 'manual' });
    for (const line of response.headers.getSetCookie()) {
      const pair = line.split(';')[0] ?? '';
      const separator = pair.indexOf('=');
      const name = pair.slice(0, separator).trim();
      const value = pair.slice(separator + 1).trim();
      const expired = /max-age=0|expires=thu, 01 jan 1970/i.test(line);
      if (!name) continue;
      if (value === '' || expired) this.cookies.delete(name);
      else this.cookies.set(name, value);
    }
    return response;
  }

  async login(email: string, password: string): Promise<void> {
    const session = await this.api.auth.login({ email, password });
    this.csrf = session.csrfToken;
  }
}

let admin: Promise<Account> | null = null;

/** The administrator created for this run, signed in once per test process. */
export function adminAccount(): Promise<Account> {
  admin ??= (async () => {
    const account = new Account();
    await account.login(control.adminEmail, control.adminPassword);
    return account;
  })();
  return admin;
}

/** Forget the cached sign-in (after the server was restarted with a fresh state, never needed otherwise). */
export function resetAdminAccount(): void {
  admin = null;
}

async function controlCall(method: 'GET' | 'POST', path: string): Promise<{ running: boolean }> {
  const response = await fetch(`${control.controlUrl}${path}`, {
    method,
    headers: { 'x-rd-control': control.controlToken },
  });
  const body = (await response.json()) as { ok: boolean; running?: boolean; message?: string };
  if (!response.ok || !body.ok) {
    throw new Error(`server control ${path} failed: ${body.message ?? response.status}`);
  }
  return { running: body.running === true };
}

/** Stops, kills and starts the real server process (it runs outside the test container). */
export const serverControl = {
  /** Orderly shutdown (SIGTERM). */
  stop: () => controlCall('POST', '/server/stop'),
  /** As if the machine lost power (SIGKILL). */
  kill: () => controlCall('POST', '/server/kill'),
  /** Starts it again and waits until it answers. */
  start: () => controlCall('POST', '/server/start'),
  status: () => controlCall('GET', '/server/status'),
};
